'use strict';
/* LAYER - the cave space. A dungeon is not a separate world: its interior is a block of ordinary tiles far outside the overworld (one block per
 * ring, at DungeonSpace.BASE), generated by the same chunk code. So collision, creatures, props, lighting, saving and multiplayer all just work
 * inside a cave. A pure function of (dungeon number, tile): an entry hall, a winding corridor, and a round boss arena. */
const DungeonSpace = {
  BASE_X: 1000000, BASE_Y: 1000000, STRIDE: 160, SIZE: 64, MARGIN: 12, COUNT: 5,
  /** Is this tile anywhere in cave space (walls and all)? */
  contains(tx, ty) { return tx >= DungeonSpace.BASE_X - 12 && ty >= DungeonSpace.BASE_Y - 12 && tx < DungeonSpace.BASE_X + DungeonSpace.STRIDE * DungeonSpace.COUNT && ty < DungeonSpace.BASE_Y + DungeonSpace.SIZE + 12; },
  /** Which dungeon (0..4) a tile belongs to, or -1. */
  indexOf(tx, ty) {
    if (!DungeonSpace.contains(tx, ty)) return -1;
    const i = Math.floor((tx - DungeonSpace.BASE_X + 12) / DungeonSpace.STRIDE); return i >= 0 && i < DungeonSpace.COUNT ? i : -1;
  },
  originOf(index) { return { x: DungeonSpace.BASE_X + index * DungeonSpace.STRIDE, y: DungeonSpace.BASE_Y }; },
  entry(index) { const o = DungeonSpace.originOf(index); return { x: o.x + 8.5, y: o.y + 31.5 }; },      // where you arrive
  exit(index) { const o = DungeonSpace.originOf(index); return { x: o.x + 5.5, y: o.y + 31.5 }; },       // the way back out
  arena(index) { const o = DungeonSpace.originOf(index); return { x: o.x + 42.5, y: o.y + 32.5 }; },     // where the boss waits
  tileAt(tx, ty) {
    const index = DungeonSpace.indexOf(tx, ty); if (index < 0) return TILE.CAVE_WALL;
    const o = DungeonSpace.originOf(index), lx = tx - o.x, ly = ty - o.y;
    if (lx < 0 || ly < 0 || lx >= DungeonSpace.SIZE || ly >= DungeonSpace.SIZE) return TILE.CAVE_WALL;
    const rough = hash3(index, lx, ly, 5) * 1.6;                                                           // ragged cave edges
    if (lx >= 4 && lx <= 13 && ly >= 27 && ly <= 36 && (lx > 4 && lx < 13 && ly > 27 && ly < 36 || rough > 0.5)) return TILE.CAVE;
    if (lx >= 13 && lx <= 33 && Math.abs(ly - (31.5 + 2.2 * Math.sin(lx * 0.55 + index))) <= 1.7) return TILE.CAVE;
    if (Math.hypot(lx - 42.5, ly - 32.5) < 13 + rough) return TILE.CAVE;
    return TILE.CAVE_WALL;
  }
};
